    position: 'absolute',
    left: '0px',
    top: (labelH + gap1) + 'px',
    width: copyW + 'px',
    height: maskH + 'px',
    color: COL.ink,
    textAlign: 'left'
  }, reqBlock);

  const mask = el('div', {
    position: 'absolute',
    left: '0px',
    top: '0px',
    width: '0px',
    height: maskH + 'px',
    overflow: 'hidden'
  }, headWrap);

  const inner = el('div', {
    position: 'absolute',
    left: '0px',
    top: '0px',
    width: copyW + 'px',
    color: COL.ink,
    textAlign: 'left'
  }, mask);
  ctx.text('req2').mount(inner, { maxLines: 2, maxFontSize: headFs, align: 'left' });

  const caretW = Math.max(3, Math.round(headFs * 0.06));
  const caret = el('div', {
    position: 'absolute',
    left: '0px',
    top: Math.round(headFs * 0.15) + 'px',
    width: caretW + 'px',
    height: Math.round(headFs * 1.02) + 'px',
    background: COL.accent,
    borderRadius: '2px',
    transform: 'none',
    opacity: '1'
  }, headWrap);

  const barTop = labelH + gap1 + maskH + gap2;
  const track = el('div', {
    position: 'absolute',
    left: '0px',
    top: barTop + 'px',
    width: '100%',
    height: barH + 'px',
    borderRadius: (barH / 2) + 'px',
    background: 'rgba(245,239,228,0.20)',
    opacity: '0'
  }, reqBlock);

  const fill = el('div', {
    position: 'absolute',
    left: '0px',
    top: '0px',
    width: '0px',
    height: barH + 'px',
    borderRadius: (barH / 2) + 'px',
    background: COL.ink
  }, track);

  const celWrap = el('div', {
    position: 'absolute',
    left: '0px',
    top: '0px',
    width: copyW + 'px',
    color: COL.ink,
    textAlign: 'left',
    opacity: '0',
    transform: 'none'
  }, copy);
  ctx.text('celebrate-head').mount(celWrap, { maxLines: 2, maxFontSize: headFs, align: 'left' });

  // ---------- credit: under the device, visible for the whole scene ----------
  const creditWrap = el('div', {
    position: 'absolute',
    left: creditX + 'px',
    top: creditY + 'px',
    width: devW + 'px',
    color: COL.ink,
    textAlign: 'center',
    zIndex: '3'
  }, stage);
  ctx.text('credit').mount(creditWrap, { maxLines: 1, maxFontSize: creditFs, align: 'center' });

  // ---------- shape placement (outside the device rectangle at all times) ----------
  const copyRight = copyX + copyW;
  const specs = [
    { side: 'left', yF: 0.06, wF: 0.11, hF: 0.11, color: COL.accent, radF: 0.5, delay: 0.00 },
    { side: 'right', yF: 0.15, wF: 0.095, hF: 0.095, color: COL.pink, radF: 0.30, delay: 0.035 },
    { side: 'left', yF: 0.50, wF: 0.13, hF: 0.042, color: COL.pink, radF: 0.5, delay: 0.07 },
    { side: 'right', yF: 0.63, wF: 0.075, hF: 0.075, color: COL.accent, radF: 0.5, delay: 0.105 },
    { side: 'left', yF: 0.885, wF: 0.055, hF: 0.055, color: COL.accent, radF: 0.5, delay: 0.14 },
    { side: 'right', yF: 0.90, wF: 0.048, hF: 0.125, color: COL.pink, radF: 0.5, delay: 0.175 }
  ];

  const shapes = [];
  for (let i = 0; i < specs.length; i++) {
    const s = specs[i];
    const nominalW = s.wF * devW;
    const nominalH = s.hF * devW;
    let availLeftEdge = pad;
    if (s.side === 'left') {
      const yProbe = devY + s.yF * devH - nominalH / 2;
      const inCopyBand = (yProbe + nominalH > copyY - pad) && (yProbe < copyBottom + pad);
      availLeftEdge = inCopyBand ? Math.max(pad, copyRight + pad) : Math.max(pad, insetL * 0.5);
    }
    let avail;
    if (s.side === 'left') {
      avail = Math.max(12, devX - pad - availLeftEdge);
    } else {
      avail = Math.max(12, W - pad - (devX + devW) - pad);
    }
    let w = Math.min(nominalW, avail);
    let h = nominalH * (w / nominalW);
    if (h > devH * 0.22) { h = devH * 0.22; }
    w = Math.round(w);
    h = Math.round(h);
    const xSettle = s.side === 'left' ? Math.round(devX - pad - w) : Math.round(devX + devW + pad);
    let y = Math.round(devY + s.yF * devH - h / 2);
    if (y < pad) { y = pad; }
    if (y + h > H - pad) { y = Math.round(H - pad - h); }
    const xHidden = s.side === 'left'
      ? Math.round(devX - w * 0.28)
      : Math.round(devX + devW - w * 0.72);
    const node = el('div', {
      position: 'absolute',
      left: xSettle + 'px',
      top: y + 'px',
      width: w + 'px',
      height: h + 'px',
      background: s.color,
      borderRadius: Math.round(Math.min(w, h) * s.radF) + 'px',
      transform: 'none',
      opacity: '0'
    }, shapesLayer);
    shapes.push({
      node: node,
      dx: xHidden - xSettle,
      w: w,
      h: h,
      phase: i * 1.37,
      delay: s.delay
    });
  }

  // ---------- pure draw(t) ----------
  const CHARS = 24;
  const TYPE_END = 36;
  const PAUSE_LAND = 72;
  const RELEASE = 126;
  const CELEBRATE_LAND = 144;
  const textW = Math.min(copyW, 0.55 * headFs * CHARS);
  const driftAmp = Math.min(W, H) * 0.0038;

  function draw(t) {
    const fr = t * 30 + 0.001;

    if (fr < PAUSE_LAND) {
      imgReady.style.opacity = '1';
      imgPaused.style.opacity = '0';
      imgCelebrate.style.opacity = '0';
    } else if (fr < RELEASE) {
      imgReady.style.opacity = '0';
      imgPaused.style.opacity = '1';
      imgCelebrate.style.opacity = '0';
    } else {
      imgReady.style.opacity = '0';
      imgPaused.style.opacity = '0';
      imgCelebrate.style.opacity = '1';
    }

    // caret typing: frames 0-36, then a solid, static caret through the freeze
    let step = 1;
    if (fr < TYPE_END) {
      step = Math.floor(clamp01(fr / TYPE_END) * CHARS + 0.000001) / CHARS;
    }
    const revealW = step >= 1 ? copyW : step * textW;
    mask.style.width = revealW.toFixed(2) + 'px';
    const caretX = step >= 1 ? textW : step * textW;
    caret.style.transform = caretX < 0.5 ? 'none' : 'translateX(' + caretX.toFixed(2) + 'px)';
    caret.style.opacity = '1';

    // cream hold bar: fills 36-72, frozen full, empties in 6 frames at release
    let q = 0;
    if (fr >= TYPE_END && fr < PAUSE_LAND) {
      q = easeOut(clamp01((fr - TYPE_END) / (PAUSE_LAND - TYPE_END)));
    } else if (fr >= PAUSE_LAND && fr < RELEASE) {
      q = 1;
    } else if (fr >= RELEASE && fr < RELEASE + 6) {
      q = 1 - clamp01((fr - RELEASE) / 6);
    }
    fill.style.width = Math.round(q * copyW) + 'px';

    let trackOp = 0;
    if (fr >= 28) {
      trackOp = easeOut(clamp01((fr - 28) / 12));
    }
    track.style.opacity = trackOp.toFixed(3);

    // request block clears, celebration headline replaces it in place
    const outE = fr < RELEASE ? 0 : easeOut(clamp01((fr - RELEASE) / 10));
    reqBlock.style.opacity = (1 - outE).toFixed(3);

    let celE = 0;
    if (fr >= RELEASE) {
      celE = easeOutExpo(clamp01((fr - RELEASE) / (CELEBRATE_LAND - RELEASE)));
    }
    celWrap.style.opacity = celE.toFixed(3);
    const rise = (1 - celE) * headFs * 0.18;
    celWrap.style.transform = rise > 0.5 ? 'translateY(' + rise.toFixed(2) + 'px)' : 'none';

    // energy shapes spill out from behind the device edges, settle by 144, then drift <1%
    const st = (fr - RELEASE) / 30;
    const dt = (fr - CELEBRATE_LAND) / 30;
    for (let i = 0; i < shapes.length; i++) {
      const s = shapes[i];
      if (st <= 0) {
        s.node.style.opacity = '0';
        s.node.style.transform = 'none';
        continue;
      }
      const k = clamp01((st - s.delay) / 0.42);
      const e = easeOutBack(k, 1.35);
      const sc = 0.62 + 0.38 * e;
      let dx = s.dx * (1 - e);
      let dy = 0;
      if (dt > 0) {
        dx += driftAmp * Math.sin(dt * 1.5 + s.phase);
        dy += driftAmp * 0.75 * Math.cos(dt * 1.15 + s.phase * 1.7);
      }
      const near = Math.abs(dx) < 0.05 && Math.abs(dy) < 0.05 && Math.abs(sc - 1) < 0.0005;
      s.node.style.transform = near
        ? 'none'
        : 'translate(' + dx.toFixed(2) + 'px,' + dy.toFixed(2) + 'px) scale(' + sc.toFixed(4) + ')';
      s.node.style.opacity = '1';
    }
  }

  const timeline = gsap.timeline({ paused: true });
  const duration = ctx.frames ? (ctx.frames.end - ctx.frames.start) / 30 : 7.2;
  ctx.OM.clock(timeline, t => draw(t), duration);
  draw(0);

  return { timeline };
});
